x_1 &= 0 + \sum_{i=1}^{10} i \cdot \text{east}[i \bmod 2 = 0] \\
y_1 &= 10 + \sum_{i=1}^{10} i \cdot \text{north}[i \bmod 2 = 1]
\end{align*} where east and north are alternating vectors: \begin{align*}
\text{east}[i] = \begin{cases}
(1, 0) & \text{if } i \bmod 2 = 0 \\
